DROP TABLE IF EXISTS `ai_extractions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_extractions` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `business_id` bigint(20) unsigned NOT NULL,
  `source_code` varchar(40) NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `frequency` enum('weekly','monthly','quarterly','yearly','custom') NOT NULL DEFAULT 'weekly',
  `extracted_json` longtext NOT NULL,
  `notes` text DEFAULT NULL,
  `status` enum('confirmed','draft') NOT NULL DEFAULT 'confirmed',
  `validation_status` enum('pending','validated','warning','review_required','approved','unavailable') NOT NULL DEFAULT 'validated',
  `validation_score` tinyint(3) unsigned DEFAULT NULL,
  `validation_json` longtext DEFAULT NULL,
  `validated_at` datetime DEFAULT NULL,
  `validation_override_by` bigint(20) unsigned DEFAULT NULL,
  `validation_override_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_ai_extract_business_source_end` (`business_id`,`source_code`,`period_end`),
  KEY `fk_ai_extract_user` (`created_by`),
  CONSTRAINT `fk_ai_extract_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ai_extract_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
