(1,1,1,'9f378027de51a1236a30c44fc51df3d886448810b19257b10d02b37d5ea430f6','{\"report_title\":\"Remedy Medspa Weekly Intelligence Dashboard | 2026-08-14 to 2026-08-21\",\"executive_summary\":\"Revenue and membership performance were positive this week: total revenue rose to $106,568.57, appointments increased to 182, active MRR reached $48,419.32, and refunds fell sharply to $141.73. The main soft spot was operational efficiency, with blended utilization down to 61.1%, average revenue per appointment down to $585.54, and revenue per scheduled hour down to $383.94. Acquisition signals were mixed-to-weaker across the available digital and call sources, while Google Business Profile remained strong at 5.0 stars. Confidence is moderated by multiple source date-range mismatches versus the selected period.\",\"overall_status\":\"mixed\",\"metrics\":[{\"label\":\"Total Revenue\",\"value\":\"$106,568.57\",\"context\":\"Boulevard KPI; current week top-line revenue.\",\"direction\":\"up\",\"source_evidence\":\"Boulevard dashboard_json.kpis.total_revenue = 106568.57; previous = 102498.28; percent_change = 3.97%.\"},{\"label\":\"Total Appointments\",\"value\":\"182\",\"context\":\"Boulevard KPI; volume increased week over week.\",\"direction\":\"up\",\"source_evidence\":\"Boulevard dashboard_json.kpis.appointments = 182; previous = 168; percent_change = 8.33%.\"},{\"label\":\"Blended Utilization\",\"value\":\"61.1%\",\"context\":\"Boulevard KPI; utilization softened versus the previous period.\",\"direction\":\"down\",\"source_evidence\":\"Boulevard dashboard_json.kpis.utilization = 61.0667; previous = 63.7077; percent_change = -4.15%.\"},{\"label\":\"Average Revenue per Appointment\",\"value\":\"$585.54\",\"context\":\"Boulevard KPI; ticket value declined week over week.\",\"direction\":\"down\",\"source_evidence\":\"Boulevard dashboard_json.kpis.average_ticket = 585.5416; previous = 610.1088; percent_change = -4.03%.\"},{\"label\":\"Current Active MRR\",\"value\":\"$48,419.32\",\"context\":\"Boulevard KPI; recurring revenue base expanded.\",\"direction\":\"up\",\"source_evidence\":\"Boulevard dashboard_json.kpis.active_mrr = 48419.32; previous = 46857.74; percent_change = 3.33%.\"},{\"label\":\"New Clients\",\"value\":\"15\",\"context\":\"Boulevard KPI; client acquisition softened slightly.\",\"direction\":\"down\",\"source_evidence\":\"Boulevard dashboard_json.kpis.new_clients = 15; previous = 16; percent_change = -6.25%.\"},{\"label\":\"Total Leads\",\"value\":\"49\",\"context\":\"Podium current period lead volume; period comparison is not safe because the source date range does not match the selected period.\",\"direction\":\"unknown\",\"source_evidence\":\"Podium values.new_leads = 49; validation notes report visible period Aug 13–Aug 20 vs selected Aug 14–Aug 21.\"},{\"label\":\"Median First Response Time\",\"value\":\"17 hr 6 min\",\"context\":\"Podium current period response speed; period comparison is not safe because the source date range does not match the selected period.\",\"direction\":\"unknown\",\"source_evidence\":\"Podium values.median_first_response_time = \'17 hr 6 min\'; validation notes report visible period Aug 13–Aug 20 vs selected Aug 14–Aug 21.\"},{\"label\":\"Google Business Profile Average Rating\",\"value\":\"5.0\",\"context\":\"GBP current rating; review volume also increased, but the source period does not match the selected week.\",\"direction\":\"unknown\",\"source_evidence\":\"GBP entry.average_rating = 5.00; entry.total_reviews = 162; entry.new_reviews = 3; validation notes indicate a period mismatch.\"}],\"wins\":[{\"title\":\"Top-line revenue grew\",\"detail\":\"Total revenue increased to $106,568.57, supported by higher gross payments and net sales.\",\"evidence\":\"Boulevard KPI total_revenue = $106,568.57 vs previous $102,498.28 (+3.97%).\"},{\"title\":\"Membership base expanded\",\"detail\":\"Recurring revenue and membership count both moved higher.\",\"evidence\":\"Active MRR = $48,419.32 (+3.33%) and active memberships = 323 (+3.86%).\"},{\"title\":\"Refunds fell sharply\",\"detail\":\"Refund volume decreased materially, improving net retention of collected revenue.\",\"evidence\":\"Refunds = $141.73 vs $458.10 previously (-69.06%).\"},{\"title\":\"Product and package revenue strengthened\",\"detail\":\"Non-service revenue increased meaningfully, especially packages.\",\"evidence\":\"All product revenue = $11,611.54 (+22.87%); package revenue = $5,348 (+49.72%).\"},{\"title\":\"Reputation remained excellent\",\"detail\":\"The business maintained a 5.0 average Google Business Profile rating with new reviews added.\",\"evidence\":\"GBP average_rating = 5.00; total_reviews = 162; new reviews = 3.\"}],\"risks\":[{\"title\":\"Utilization declined\",\"detail\":\"Blended utilization fell to 61.1%, indicating less efficient use of scheduled capacity.\",\"evidence\":\"Boulevard KPI utilization = 61.0667% vs 63.7077% previously.\"},{\"title\":\"Per-appointment economics softened\",\"detail\":\"Average revenue per appointment and revenue per scheduled hour both declined.\",\"evidence\":\"Boulevard KPI average_ticket = $585.54 (-4.03%); revenue_per_hour = $383.94 (-7.84%).\"},{\"title\":\"Lead generation signals weakened\",\"detail\":\"Available lead sources showed lower volume, but their source periods do not match the selected week, so the trend should be treated cautiously.\",\"evidence\":\"Growth99 new_leads = 49; Podium new_leads = 49; both source validations flag period mismatches.\"},{\"title\":\"Response time remains long\",\"detail\":\"Podium median first response time is still measured in hours, which may limit lead conversion.\",\"evidence\":\"Podium median_first_response_time = 17 hr 6 min.\"},{\"title\":\"Provider demand is concentrated\",\"detail\":\"One provider generated a large share of service revenue and ran above 100% utilization, which suggests uneven capacity distribution.\",\"evidence\":\"Kristina Thissen: service_revenue = $35,280; utilization = 104.48%; appointments = 58.\"}],\"opportunities\":[{\"title\":\"Rebalance provider capacity\",\"detail\":\"Shift schedules or demand allocation toward underutilized providers to improve blended utilization and revenue per scheduled hour.\",\"evidence\":\"Provider utilization ranged from 104.48% for Kristina Thissen to 18.75% for Hayley Marshall; overall blended utilization was 61.1%.\"},{\"title\":\"Convert stronger product and package demand\",\"detail\":\"The step-up in product and package revenue can be used to lift average ticket and offset softer service economics.\",\"evidence\":\"Product revenue = $11,611.54 (+22.87%) and package revenue = $5,348 (+49.72%).\"},{\"title\":\"Strengthen lead response and follow-up\",\"detail\":\"Reducing response time and improving follow-up could help reverse softer lead and acquisition signals.\",\"evidence\":\"Podium median first response time = 17 hr 6 min; Growth99 total leads = 49 with period mismatch caveat.\"},{\"title\":\"Build on membership momentum\",\"detail\":\"Memberships and active MRR are trending up and could be expanded further with targeted renewals or upgrades.\",\"evidence\":\"Active memberships = 323; active MRR = $48,419.32; membership revenue = $14,713.\"},{\"title\":\"Leverage strong review profile\",\"detail\":\"A 5.0 rating provides a strong trust signal that can be reinforced in local marketing and conversion efforts.\",\"evidence\":\"GBP average_rating = 5.00; new_reviews = 3; total_reviews = 162.\"}],\"recommendations\":[{\"priority\":\"high\",\"title\":\"Rebalance scheduling to lift utilization\",\"action\":\"Review provider schedules and appointment allocation to reduce the gap between overbooked and underbooked team members, with a focus on improving blended utilization and revenue per scheduled hour.\",\"rationale\":\"Utilization fell to 61.1% while one provider ran at 104.48% and others were far below capacity.\"},{\"priority\":\"high\",\"title\":\"Tighten lead response workflows\",\"action\":\"Audit inquiry handling and follow-up speed across lead sources, then set a faster response standard for new inquiries.\",\"rationale\":\"Podium shows a 17 hr 6 min median first response time, and available lead volumes were softer despite the source-period caveat.\"},{\"priority\":\"medium\",\"title\":\"Double down on product and package conversion\",\"action\":\"Use the stronger product and package performance to support bundles, add-ons, and higher-value recommendations during appointments.\",\"rationale\":\"Product revenue rose 22.87% and package revenue rose 49.72%, while average ticket declined.\"},{\"priority\":\"medium\",\"title\":\"Protect and expand memberships\",\"action\":\"Continue membership-focused selling and retention efforts to build on the higher active MRR and active membership base.\",\"rationale\":\"Active MRR increased to $48,419.32 and active memberships rose to 323.\"},{\"priority\":\"low\",\"title\":\"Maintain review momentum\",\"action\":\"Keep review generation active and surface the 5.0 rating in local marketing and conversion assets.\",\"rationale\":\"The GBP profile has 162 total reviews and a 5.0 average rating.\"}],\"data_quality_notes\":[\"Boulevard reporting files are labeled 2026-08-13 to 2026-08-20, while the selected report period is 2026-08-14 to 2026-08-21; period-to-period comparison is therefore less reliable.\",\"Google Analytics 4 visible data is for Aug 13–Aug 19, not the selected Aug 14–Aug 21 period; page_views and several action metrics are not visible in the snapshot.\",\"Growth99 visible data is for Aug 14–Aug 20, not the selected Aug 14–Aug 21 period; CallRail metrics are not visible and are null.\",\"Podium visible data is for Aug 13–Aug 20, not the selected Aug 14–Aug 21 period; several call metrics and peak_call_time are not visible and are null.\",\"Multiple sources required review and admin override before approval; use cross-source trend interpretation cautiously.\",\"No sources are held in the current period, but several have explicit period-mismatch warnings in validation.\"]}','openai','gpt-5.4-mini-2026-03-17','resp_051a62a70bec39ac016a98004d9cdc87d18f128eeb5ac1b865','ai-weekly-v1-openai',20122,4707,2508,24829,6,'2026-09-02 16:24:35');
