--
-- Table structure for table `ai_weekly_reports`
--

DROP TABLE IF EXISTS `ai_weekly_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `ai_weekly_reports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `business_id` bigint(20) unsigned NOT NULL,
  `period_start` date NOT NULL,
  `period_end` date NOT NULL,
  `source_text` mediumtext NOT NULL,
  `source_hash` char(64) NOT NULL,
  `generated_json` longtext DEFAULT NULL,
  `generated_source_hash` char(64) DEFAULT NULL,
  `status` varchar(20) NOT NULL DEFAULT 'draft',
  `current_version` int(10) unsigned NOT NULL DEFAULT 0,
  `generated_model` varchar(100) DEFAULT NULL,
  `prompt_version` varchar(80) NOT NULL DEFAULT 'ai-weekly-v1-openai',
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `reviewed_by` bigint(20) unsigned DEFAULT NULL,
  `published_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `published_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_ai_weekly_business_status` (`business_id`,`status`,`period_end`),
  KEY `idx_ai_weekly_published` (`business_id`,`status`,`published_at`),
  KEY `fk_ai_weekly_created_user` (`created_by`),
  KEY `fk_ai_weekly_updated_user` (`updated_by`),
  KEY `fk_ai_weekly_reviewed_user` (`reviewed_by`),
  KEY `fk_ai_weekly_published_user` (`published_by`),
  CONSTRAINT `fk_ai_weekly_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_ai_weekly_created_user` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_weekly_published_user` FOREIGN KEY (`published_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_weekly_reviewed_user` FOREIGN KEY (`reviewed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_ai_weekly_updated_user` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

