(1,2,'2026-08-14','2026-08-21','{\"business\":{\"id\":2,\"name\":\"Remedy Medspa\"},\"current_period\":{\"held_sources\":[],\"sources\":{\"boulevard\":{\"batch\":{\"business_id\":2,\"completed_at\":\"2026-08-21 08:09:12\",\"completeness_score\":\"90.90\",\"created_at\":\"2026-08-21 08:09:01\",\"dashboard_json\":\"{\\\"meta\\\":{\\\"period_start\\\":\\\"2026-08-14\\\",\\\"period_end\\\":\\\"2026-08-21\\\",\\\"frequency\\\":\\\"weekly\\\",\\\"generated_at\\\":\\\"2026-08-21T08:09:01+00:00\\\"},\\\"kpis\\\":{\\\"total_revenue\\\":{\\\"label\\\":\\\"Total Revenue\\\",\\\"value\\\":106568.57,\\\"format\\\":\\\"currency\\\",\\\"direction\\\":\\\"up\\\",\\\"previous\\\":102498.28,\\\"change\\\":4070.290000000008,\\\"percent_change\\\":3.971081270827187,\\\"sentiment\\\":\\\"positive\\\"},\\\"net_sales\\\":{\\\"label\\\":\\\"Net Sales\\\",\\\"value\\\":106556.84,\\\"format\\\":\\\"currency\\\",\\\"direction\\\":\\\"up\\\",\\\"previous\\\":102490.18,\\\"change\\\":4066.6600000000035,\\\"percent_change\\\":3.967853310434233,\\\"sentiment\\\":\\\"positive\\\"},\\\"gross_payments\\\":{\\\"label\\\":\\\"Gross Payments\\\",\\\"value\\\":106698.57,\\\"format\\\":\\\"currency\\\",\\\"direction\\\":\\\"up\\\",\\\"previous\\\":102948.28,\\\"change\\\":3750.290000000008,\\\"percent_change\\\":3.642887477090446,\\\"sentiment\\\":\\\"positive\\\"},\\\"refunds\\\":{\\\"label\\\":\\\"Refunds\\\",\\\"value\\\":141.73,\\\"format\\\":\\\"currency\\\",\\\"direction\\\":\\\"down\\\",\\\"previous\\\":458.1,\\\"change\\\":-316.37,\\\"percent_change\\\":-69.06134031870769,\\\"sentiment\\\":\\\"positive\\\"},\\\"service_revenue\\\":{\\\"label\\\":\\\"Service Revenue\\\",\\\"value\\\":71988.59,\\\"format\\\":\\\"currency\\\",\\\"direction\\\":\\\"up\\\",\\\"previous\\\":72694.01,\\\"change\\\":-705.4199999999983,\\\"percent_change\\\":-0.9703963228882246,\\\"sentiment\\\":\\\"negative\\\"},\\\"product_revenue\\\":{\\\"label\\\":\\\"All Product Revenue\\\",\\\"value\\\":11611.54,\\\"format\\\":\\\"c