--
-- Table structure for table `boulevard_sync_items`
--

DROP TABLE IF EXISTS `boulevard_sync_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `boulevard_sync_items` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sync_run_id` bigint(20) unsigned NOT NULL,
  `business_id` bigint(20) unsigned NOT NULL,
  `report_type_id` bigint(20) unsigned NOT NULL,
  `boulevard_report_id` varchar(220) NOT NULL,
  `boulevard_report_name` varchar(255) DEFAULT NULL,
  `date_filter_attribute` varchar(255) DEFAULT NULL,
  `interval_value` varchar(40) DEFAULT NULL,
  `report_export_id` varchar(220) DEFAULT NULL,
  `file_url` text DEFAULT NULL,
  `current_export_at` datetime DEFAULT NULL,
  `status` enum('queued','requesting','requested','accepted','generating','waiting','retry_scheduled','downloading','validating','validated','downloaded','processing','processed','completed','needs_attention','timed_out','failed') NOT NULL DEFAULT 'queued',
  `attempt_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `provider_check_count` smallint(5) unsigned NOT NULL DEFAULT 0,
  `max_attempts` smallint(5) unsigned NOT NULL DEFAULT 5,
  `provider_payload_json` longtext DEFAULT NULL,
  `validation_json` longtext DEFAULT NULL,
  `checksum_sha256` char(64) DEFAULT NULL,
  `local_path` varchar(700) DEFAULT NULL,
  `header_score` tinyint(3) unsigned DEFAULT NULL,
  `row_count` int(10) unsigned NOT NULL DEFAULT 0,
  `warning_count` int(10) unsigned NOT NULL DEFAULT 0,
  `error_message` text DEFAULT NULL,
  `failure_code` varchar(80) DEFAULT NULL,
  `last_http_status` smallint(5) unsigned DEFAULT NULL,
  `last_provider_check_at` datetime DEFAULT NULL,
  `next_attempt_at` datetime DEFAULT NULL,
  `last_error_at` datetime DEFAULT NULL,
  `webhook_received_at` datetime DEFAULT NULL,
  `completion_source` enum('webhook','poll','download_probe','manual') DEFAULT NULL,
  `requested_at` datetime DEFAULT NULL,
  `downloaded_at` datetime DEFAULT NULL,
  `processed_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_blvd_sync_item_type` (`sync_run_id`,`report_type_id`),
  KEY `idx_blvd_sync_item_status` (`sync_run_id`,`status`),
  KEY `fk_blvd_sync_item_business` (`business_id`),
  KEY `fk_blvd_sync_item_type` (`report_type_id`),
  CONSTRAINT `fk_blvd_sync_item_business` FOREIGN KEY (`business_id`) REFERENCES `businesses` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_blvd_sync_item_run` FOREIGN KEY (`sync_run_id`) REFERENCES `boulevard_sync_runs` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_blvd_sync_item_type` FOREIGN KEY (`report_type_id`) REFERENCES `report_types` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

